#!/usr/bin/env bash
# Frayd bootstrap (Linux/macOS) — generated by the web installer.
# Args: LIBRARY_PATH
set -e
LIB="$1"
have() { command -v "$1" >/dev/null 2>&1; }

echo "== Frayd installer =="
echo "Media folder: ${LIB:-<unset>}"

# --- deps ---
if have apt-get; then
  sudo apt-get update -qq && sudo apt-get install -y -qq git curl build-essential pkg-config libsqlite3-dev unzip unrar-free ffmpeg >/dev/null
elif have dnf; then
  sudo dnf install -y -q git curl gcc gcc-c++ make sqlite-devel unzip unrar ffmpeg >/dev/null
elif have pacman; then
  sudo pacman -S --noconfirm --needed git curl base-devel sqlite unzip unrar ffmpeg >/dev/null
elif have brew; then
  brew install -q git sqlite unzip unrar ffmpeg >/dev/null 2>&1 || true
fi

if ! have cargo; then
  echo "[*] Installing Rust toolchain..."
  curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --default-toolchain stable
  . "$HOME/.cargo/env"
fi

# --- clone / update ---
cd "$HOME"
if [ -d Frayd ]; then (cd Frayd && git pull --ff-only) else git clone https://github.com/kattiest/Frayd.git; fi

# --- library path ---
if [ -z "$LIB" ]; then
  printf "Path to your media folder [~/Media]: "
  read -r LIB
  LIB="${LIB:-$HOME/Media}"
fi
mkdir -p "$LIB"
LIB="$(cd "$LIB" && pwd)"

# --- build ---
echo "[*] Building (first build takes a few minutes)..."
cd Frayd/server
cargo build --release

# --- env file ---
tee .env >/dev/null <<EOF
FRAYD_LIBRARY=$LIB
# Public internet exposure? Uncomment for shorter sessions (days):
# FRAYD_SESSION_DAYS=7
EOF

# --- autostart: systemd user unit (Linux) or LaunchAgent (macOS) ---
if have systemctl; then
  mkdir -p "$HOME/.config/systemd/user"
  cat > "$HOME/.config/systemd/user/frayd.service" <<EOF
[Unit]
Description=Frayd media server
After=network-online.target

[Service]
WorkingDirectory=$PWD
EnvironmentFile=$PWD/.env
ExecStart=$PWD/target/release/frayd-server
Restart=on-failure

[Install]
WantedBy=default.target
EOF
  systemctl --user daemon-reload
  systemctl --user enable --now frayd.service
  loginctl show-user "$USER" >/dev/null 2>&1 && sudo loginctl enable-linger "$USER" 2>/dev/null || true
  echo "[OK] systemd user service installed (starts on boot)"
elif have launchctl; then
  mkdir -p "$HOME/Library/LaunchAgents"
  PL="$HOME/Library/LaunchAgents/io.github.kattiest.frayd.plist"
  cat > "$PL" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>io.github.kattiest.frayd</string>
  <key>WorkingDirectory</key><string>$PWD</string>
  <key>ProgramArguments</key><array><string>$PWD/target/release/frayd-server</string></array>
  <key>EnvironmentVariables</key><dict><key>FRAYD_LIBRARY</key><string>$LIB</string></dict>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
</dict></plist>
EOF
  launchctl load "$PL"
  echo "[OK] LaunchAgent installed (starts on login)"
else
  echo "[*] No systemd/launchd — start manually:"
  echo "    FRAYD_LIBRARY=$LIB ./target/release/frayd-server"
fi

echo
echo "[OK] Frayd running at http://localhost:8484"
echo "     First login becomes the admin account."
